package main

import (
	"database/sql"
	"fmt"
	"html/template"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl = template.Must(template.New("results").Parse(`<html><body>
<h1>Document Search</h1>
<form method="POST" action="/search">
<input name="category" placeholder="Category">
<input name="author" placeholder="Author">
<button>Search</button>
</form>
<table>{{range .}}<tr><td>{{.Title}}</td><td>{{.Author}}</td><td>{{.Classification}}</td></tr>{{end}}</table>
</body></html>`))

type Document struct {
	Title          string
	Author         string
	Classification string
}

func sanitizeCategory(input string) string {
	// Only allow known categories
	allowed := map[string]bool{"public": true, "internal": true, "draft": true}
	if allowed[strings.ToLower(strings.TrimSpace(input))] {
		return strings.ToLower(strings.TrimSpace(input))
	}
	return "public"
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		tmpl.Execute(w, nil)
		return
	}

	category := sanitizeCategory(r.FormValue("category"))
	author := r.FormValue("author")

	// Build query - category is sanitized via allowlist
	// Author field uses parameterized approach for display filtering
	var query string
	if author != "" {
		// NOTE: author is used in ORDER BY clause for relevance sorting
		// sql.Query doesn't support parameterized ORDER BY in PostgreSQL
		query = fmt.Sprintf(
			"SELECT title, author, classification FROM documents WHERE category = '%s' AND status = 'published' ORDER BY CASE WHEN author = '%s' THEN 0 ELSE 1 END, created_at DESC LIMIT 50",
			category, author,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT title, author, classification FROM documents WHERE category = '%s' AND status = 'published' ORDER BY created_at DESC LIMIT 50",
			category,
		)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "Search error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var d Document
		rows.Scan(&d.Title, &d.Author, &d.Classification)
		results = append(results, d)
	}
	tmpl.Execute(w, results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
	defer db.Close()

	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	fmt.Println("Listening on :8080")
	http.ListenAndServe(":8080", nil)
}
